302	    /**
303	     * The owner's membership points, accumulated from four factors: start at 0, add 2
304	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
305	     * household of 3 or more members, and add 3 when the owner's tenure spans at least
306	     * one elapsed fiscal year. The tenure points are the only route to 6 or more:
307	     * because a newly created owner has zero elapsed fiscal years of tenure, a new owner
308	     * scores at most 5 points (2 email + 1 namesake + 2 household).
309	     */
310	    @Transient
311	    public int getMembershipPoints() {
312	        int points = 0;
313	        if (this.email != null && !this.email.isBlank()) {
314	            points += 2;
315	        }
316	        if (this.namesakeCount != null && this.namesakeCount == 0) {
317	            points += 1;
318	        }
319	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
320	            points += 2;
321	        }
322	        if (getTenureFiscalYears() >= 1) {
323	            points += 3;
324	        }
325	        return points;
326	    }
327	
328	    /**
329	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
330	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
331	     * created owner scores at most 5 points (tenure being the only route to 6), a new
332	     * owner never exceeds level 3.
333	     *
334	     * <p>The result is then bounded by {@code membershipLevelCap} when one is set: a new
335	     * owner's level cannot exceed one above the highest level among the existing members
336	     * of their household, so the reported level is the lesser of the points-derived level
337	     * and that cap.
338	     */
339	    @Transient
340	    public int getMembershipLevel() {
341	        int level = pointsLevel();
342	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
343	            return this.membershipLevelCap;
344	        }
345	        return level;
346	    }
347	
348	    /** The uncapped, points-derived membership level (see {@link #getMembershipLevel()}). */
349	    private int pointsLevel() {
350	        int points = getMembershipPoints();
351	        if (points <= 1) {
352	            return 1;
353	        }
354	        if (points <= 3) {
355	            return 2;
356	        }
357	        if (points <= 5) {
358	            return 3;
359	        }
360	        return 4;
361	    }
362	
363	    /**
364	     * The owner's tenure counted in elapsed fiscal years: the number of fiscal-year
365	     * boundaries (each 1 July) crossed between {@code registrationDate} and today, i.e.
366	     * {@code fiscalYearOf(today) - fiscalYearOf(registrationDate)}. Zero when no
367	     * registration date is set, and zero for an owner registered in the current fiscal
368	     * year, so the tenure point of {@link #getMembershipLevel()} is never earned at
369	     * creation.
370	     */
371	    @Transient
372	    public long getTenureFiscalYears() {
373	        if (this.registrationDate == null) {
374	            return 0;
375	        }
376	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate);
377	    }
378	
379	    /**
380	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, derived from the
381	     * business-day-adjusted {@code registrationDate}. The fiscal year starts on 1 July,
382	     * so a date in July or later belongs to the fiscal year named by its own calendar
383	     * year, and a date in January to June belongs to the fiscal year that started the
384	     * previous 1 July. {@code YY} is the last two digits of that fiscal year. Returns
385	     * {@code null} when no registration date is set.
386	     */
387	    @Transient
388	    public String getFiscalYear() {
389	        if (this.registrationDate == null) {
390	            return null;
391	        }
392	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
393	    }
394	
395	    /**
396	     * The fiscal year (named by the calendar year in which its 1 July start falls) that
397	     * {@code date} belongs to. July onward is the current calendar year; January to June
398	     * belongs to the fiscal year that began the previous 1 July.
399	     */
400	    private static int fiscalYearOf(LocalDate date) {
401	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
402	                ? date.getYear() : date.getYear() - 1;
403	    }
404	
405	    /**
406	     * The owner's canonical region, preferring the postcode over the city.
407	     *
408	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
409	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
410	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
411	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
412	     * backs both the {@code locality} field and the {@code REGION} segment of the
413	     * {@code memberId}, so the two always agree.
414	     */
415	    @Transient
416	    public String getRegion() {
417	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
418	            int value = Integer.parseInt(this.postcode);
419	            if (value >= 2000 && value <= 2099) {
420	                return "NSW";
421	            }
422	            if (value >= 3000 && value <= 3099) {
423	                return "VIC";
424	            }
425	            if (value >= 4000 && value <= 4099) {
426	                return "QLD";
427	            }
428	        }
429	        if ("Sydney".equals(this.city)) {
430	            return "NSW";
431	        }
432	        if ("Melbourne".equals(this.city)) {
433	            return "VIC";
434	        }
435	        if ("Brisbane".equals(this.city)) {
436	            return "QLD";
437	        }
438	        return "UNKNOWN";
439	    }
440	
441	    /**
442	     * The owner's segment, formatted {@code '<TIER>_<AREA>'} — one of
443	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
444	     * {@code STANDARD_REGIONAL}. The {@code TIER} is {@code PREMIUM} when
445	     * {@link #getMembershipLevel()} is 3 or more, otherwise {@code STANDARD}. The
446	     * {@code AREA} is {@code METRO} when {@link #getRegion()} is a known region (NSW, VIC
447	     * or QLD), otherwise {@code REGIONAL}.
448	     */
449	    @Transient
450	    public String getOwnerSegment() {
451	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
452	        String area = "UNKNOWN".equals(getRegion()) ? "REGIONAL" : "METRO";
453	        return tier + "_" + area;
454	    }
455	
456	    /**
457	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
458	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
459	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
460	     */
461	    @Transient
462	    public String getTimezone() {
463	        switch (getRegion()) {
464	            case "NSW":
465	                return "Australia/Sydney";
466	            case "VIC":
467	                return "Australia/Melbourne";
468	            case "QLD":
469	                return "Australia/Brisbane";
470	            default:
471	                return null;
472	        }
473	    }
474	
475	    /**
476	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
477	     * present, otherwise {@code PHONE}.
478	     */
479	    @Transient
480	    public String getContactPreference() {
481	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
482	    }
483	
484	    /**
485	     * The owner's derived duplicate-detection key: the SHA-256 hex digest over the
486	     * normalized (E.164) telephone, the lower-cased email (or empty when absent) and the
487	     * Soundex code of the last name, joined by {@code '|'} before hashing. The result is a
488	     * 64-character lower-case hex string. Two owners are duplicates only when their whole
489	     * identity keys are equal; because the telephone is part of the key, two owners with
490	     * the same last name and postcode but different telephones have different keys (and are
491	     * a soft match, not a hard duplicate).
492	     */
493	    @Transient
494	    public String getIdentityKey() {
495	        String tel = this.telephone == null ? "" : this.telephone;
496	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
497	        String lastNameCode = Soundex.encode(getLastName());
498	        return sha256hex(tel + "|" + mail + "|" + lastNameCode);
499	    }
500	
501	    /** Lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
502	    private static String sha256hex(String value) {
503	        try {
504	            byte[] digest = MessageDigest.getInstance("SHA-256")
505	                    .digest(value.getBytes(StandardCharsets.UTF_8));
506	            StringBuilder sb = new StringBuilder(digest.length * 2);
507	            for (byte b : digest) {
508	                sb.append(String.format("%02x", b));
509	            }
510	            return sb.toString();
511	        }
512	        catch (NoSuchAlgorithmException e) {
513	            throw new IllegalStateException("SHA-256 not available", e);
514	        }
515	    }
516	
517	    protected Set<Pet> getPetsInternal() {
518	        if (this.pets == null) {
519	            this.pets = new HashSet<>();
520	        }
521	        return this.pets;
522	    }
523	
