528	    public List<Pet> getPets() {
529	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
530	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
531	        return Collections.unmodifiableList(sortedPets);
532	    }
533	
534	    public void setPets(List<Pet> pets) {
535	        this.pets = new HashSet<>(pets);
536	    }
537	
538	    public void addPet(Pet pet) {
539	        getPetsInternal().add(pet);
540	        pet.setOwner(this);
541	    }
542	
543	    /**
544	     * Return the Pet with the given name, or null if none found for this Owner.
545	     *
546	     * @param name to test
547	     * @return true if pet name is already in use
548	     */
549	    public Pet getPet(String name) {
550	        return getPet(name, false);
551	    }
552	
553	    /**
554	     * Return the Pet with the given name, or null if none found for this Owner.
555	     *
556	     * @param name to test
557	     * @return true if pet name is already in use
558	     */
559	    public Pet getPet(String name, boolean ignoreNew) {
560	        name = name.toLowerCase();
561	        for (Pet pet : getPetsInternal()) {
562	            if (!ignoreNew || !pet.isNew()) {
563	                String compName = pet.getName();
564	                compName = compName.toLowerCase();
565	                if (compName.equals(name)) {
566	                    return pet;
567	                }
568	            }
569	        }
570	        return null;
571	    }
572	
573	    public Pet getPet(Integer petId) {
574	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
575	    }
576	
577	    @Override
578	    public String toString() {
579	        return new ToStringCreator(this)
580	
581	            .append("id", this.getId())
582	            .append("new", this.isNew())
583	            .append("lastName", this.getLastName())
584	            .append("firstName", this.getFirstName())
585	            .append("address", this.address)
586	            .append("city", this.city)
587	            .append("telephone", this.telephone)
588	            .toString();
589	    }
590	}
